<?php if(!empty($article)):?><article class="article-page"><div class="article-cover"><img src="<?=e($article['image_url'])?>" alt="<?=e($article['title'])?>"><span class="eyebrow"><?=e(strtoupper($article['category']))?> · <?=e(date('d M Y',strtotime($article['created_at'])))?></span></div><div class="article-content"><a class="text-link" href="<?=e(url('journal'))?>">← ALL JOURNAL STORIES</a><h1><?=e($article['title'])?></h1><p class="article-deck"><?=e($article['excerpt'])?></p><div class="article-body"><?php $body=str_replace(['\\r\\n','\\n'],"\n",trim($article['body']));foreach(preg_split('/\R\s*\R/', $body) as $paragraph):?><p><?=nl2br(e($paragraph))?></p><?php endforeach;?></div><div class="article-author">WORDS BY <strong><?=e($article['author'])?></strong></div></div></article><?php else:?><section class="page-hero"><span class="eyebrow">THE FITZENO JOURNAL</span><h1>MOVE SMARTER.<br><em>LIVE A LITTLE.</em></h1><p>Useful ideas for a stronger everyday in Sri Lanka.</p></section><section class="journal-grid section-pad"><?php foreach($articles as $articleItem):?><a class="story-card" href="<?=e(url('journal/'.$articleItem['slug']))?>"><div class="story-image"><img src="<?=e($articleItem['image_url'])?>" alt="<?=e($articleItem['title'])?>" loading="lazy"><span>READ STORY ↗</span></div><div class="story-meta"><span><?=e($articleItem['category'])?></span><time><?=e(date('d M Y',strtotime($articleItem['created_at'])))?></time></div><h3><?=e($articleItem['title'])?></h3><p><?=e($articleItem['excerpt'])?></p></a><?php endforeach;?></section><?php endif;?>
